import { useEffect, useRef, useState } from "react";
import type { LoadingPhase, LoadingTiming } from "./types";

type Options = LoadingTiming & {
  /** When false the hook settles on "done" immediately and never animates. */
  enabled: boolean;
  /** Show only on the first full page load of a browser session. */
  oncePerSession?: boolean;
};

/**
 * Drives the loader's progress value and lifecycle.
 *
 * Progress eases toward `creepCeiling` across `minVisible` rather than tracking
 * real asset bytes — browsers expose no reliable total, and a bar that stalls
 * at an honest 40% reads worse than one that moves. The jump to 100% is the
 * honest part: it only happens once the document has actually finished loading.
 *
 * Always reports "loading" on the first render so the server-rendered markup
 * and the first client render agree; the decision to skip is made in an effect.
 */
const SESSION_KEY = "kr-loading-shown";

export function useLoadingProgress({
  enabled,
  oncePerSession = false,
  minVisible,
  exit,
  creepCeiling,
  creepEasing,
}: Options) {
  const [progress, setProgress] = useState(0);
  const [phase, setPhase] = useState<LoadingPhase>("loading");

  // Latest values without re-running the effect and restarting the animation.
  const opts = useRef({ minVisible, exit, creepCeiling, creepEasing });
  opts.current = { minVisible, exit, creepCeiling, creepEasing };

  useEffect(() => {
    if (!enabled || (oncePerSession && alreadyShownThisSession())) {
      setPhase("done");
      setProgress(1);
      return;
    }

    const start = Date.now();
    let frame = 0;
    let exitTimer: ReturnType<typeof setTimeout> | undefined;
    let cancelled = false;

    // `load` may already have fired by the time React mounts.
    let loaded = document.readyState === "complete";
    const onLoad = () => {
      loaded = true;
    };
    if (!loaded) window.addEventListener("load", onLoad);

    const finish = () => {
      if (cancelled) return;
      setProgress(1);
      setPhase("exiting");
      exitTimer = setTimeout(() => {
        if (!cancelled) setPhase("done");
      }, opts.current.exit);
    };

    const tick = () => {
      if (cancelled) return;

      const { minVisible: min, creepCeiling, creepEasing } = opts.current;
      const elapsed = Date.now() - start;
      const t = Math.min(elapsed / Math.max(min, 1), 1);

      // Decelerating approach — fast off the line, slow into the ceiling.
      setProgress(creepCeiling * (1 - Math.pow(1 - t, creepEasing)));

      if (loaded && elapsed >= min) {
        finish();
        return;
      }

      frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);

    return () => {
      cancelled = true;
      cancelAnimationFrame(frame);
      if (exitTimer) clearTimeout(exitTimer);
      window.removeEventListener("load", onLoad);
    };
  }, [enabled, oncePerSession]);

  return { progress, phase };
}

/**
 * Reads and sets the once-per-session marker. Storage throws in some privacy
 * modes; treating that as "not yet shown" fails toward showing the loader,
 * which is the harmless direction.
 */
function alreadyShownThisSession(): boolean {
  try {
    if (sessionStorage.getItem(SESSION_KEY)) return true;
    sessionStorage.setItem(SESSION_KEY, "1");
  } catch {
    return false;
  }
  return false;
}

export default useLoadingProgress;
