// Typography follows the reference the client picked (MTC-SBS-001): big,
// light-weight geometric-sans titles with tight tracking, a small quiet
// eyebrow above them, and calm grey body copy.
//
//   heading  Manrope        titles at weight 500, never bold — size does the work
//   body     Jost           navigation, buttons, forms, paragraphs
//   brand    Playfair Display  the "SOLD BY SAJRA" wordmark only, kept from the
//                           current soldbysajra.com so the logo is unchanged
//
// To try a different face, change it here and the family in gatsby-ssr.tsx.
// Nothing else in the codebase names a typeface.

const heading = `"Manrope", "Jost", -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif`;
const sans = `"Jost", "Helvetica Neue", -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif`;
const brand = `"Playfair Display", Georgia, "Times New Roman", serif`;

const typography = {
  heading,
  body: sans,
  brand,

  weight: {
    regular: 400,
    medium: 500,
    semibold: 600,
    bold: 700,
    /** Titles. Deliberately light — see the note at the top. */
    heading: 500,
  },

  tracking: {
    /** Large titles read loose at default spacing. */
    tight: "-0.035em",
    normal: "0",
    wide: "0.06em",
    wider: "0.16em",
  },
};

export default typography;
