// Styling for the loading screen. Swap this module (via
// config/loading--template.ts) to restyle the loader without touching a
// component — the same layering used by templates/gh-leads/default-template.
//
// A class-based stylesheet string, injected via <style>, plus the copy and
// the timing the mechanism reads. Everything here derives from template-1's
// tokens; no hex or pixel value is written twice.

import template1 from "./template-1";

export type LoadingLabels = {
  /** Wordmark shown top-left. */
  wordmark: string;
  /** Accent character trailing the wordmark. Empty string to omit. */
  wordmarkAccent: string;
  /** Small label beneath the progress rule. `{n}` is replaced by 0-100. */
  counter: string;
  /** Screen-reader announcement while the overlay is up. */
  srLabel: string;
};

export type LoadingTemplate = {
  /** Class-based stylesheet. Injected via <style>. */
  css: string;
  /** Root class name the mechanism toggles state modifiers onto. */
  rootClass: string;
  /** Durations and progress-curve shape. */
  timing: typeof template1.timing;
  /** All user-facing copy. */
  labels: LoadingLabels;
};

const { color, layout, spacing, timing, typography } = template1;

const labels: LoadingLabels = {
  wordmark: "Sold by Sajra",
  wordmarkAccent: ".",
  counter: "{n}",
  srLabel: "Loading",
};

const css = `
.kr-loading {
  position: fixed;
  inset: 0;
  z-index: ${layout.zIndex};
  display: flex;
  align-items: center;
  justify-content: center;
  background: ${color.background};
  background-image: radial-gradient(
    120% 90% at 50% 50%,
    ${color.background} 0%,
    ${color.backgroundDeep} 100%
  );
  opacity: 1;
  transform: translateY(0);
  transition:
    opacity ${timing.exit}ms cubic-bezier(.4, 0, .2, 1),
    transform ${timing.exit}ms cubic-bezier(.4, 0, .2, 1);
}

/* Exit: lift and fade as one motion. */
.kr-loading--exiting {
  opacity: 0;
  transform: translateY(${layout.exitTranslate}px);
  pointer-events: none;
}

/* ── wordmark ─────────────────────────────────────────── */
.kr-loading__wordmark {
  position: absolute;
  top: ${spacing.edgeY}px;
  left: ${spacing.edgeX}px;
  margin: 0;
  color: ${color.wordmark};
  font-family: ${typography.wordmarkFamily};
  font-size: ${typography.wordmarkSize}px;
  font-weight: ${typography.wordmarkWeight};
  letter-spacing: ${typography.wordmarkTracking};
  line-height: 1;
  user-select: none;
}
.kr-loading__wordmark-accent { color: ${color.wordmarkAccent}; }

/* ── centre stack ─────────────────────────────────────── */
.kr-loading__center {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: ${spacing.counterGap}px;
}

/* ── progress rule ────────────────────────────────────── */
.kr-loading__track {
  position: relative;
  width: ${layout.trackWidthWide}px;
  height: ${layout.trackHeight}px;
  border-radius: ${layout.trackRadius}px;
  background: ${color.track};
  overflow: hidden;
}
.kr-loading__fill {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: ${color.fill};
  transform-origin: left center;
  transform: scaleX(0);
  transition: transform .32s cubic-bezier(.33, 1, .68, 1);
  will-change: transform;
}

/* ── counter ──────────────────────────────────────────── */
.kr-loading__counter {
  color: ${color.counter};
  font-family: ${typography.counterFamily};
  font-size: ${typography.counterSize}px;
  font-weight: ${typography.counterWeight};
  letter-spacing: ${typography.counterTracking};
  font-variant-numeric: tabular-nums;
  line-height: 1;
  user-select: none;
}

/* ── responsive ───────────────────────────────────────── */
@media (max-width: ${layout.compactBelow}px) {
  .kr-loading__wordmark {
    top: ${spacing.edgeYCompact}px;
    left: ${spacing.edgeXCompact}px;
    font-size: ${typography.wordmarkSizeCompact}px;
  }
  .kr-loading__track { width: ${layout.trackWidth}px; }
}

/* Respect a reduced-motion preference: cross-fade, no travel, no easing show. */
@media (prefers-reduced-motion: reduce) {
  .kr-loading,
  .kr-loading__fill {
    transition-duration: .01ms;
  }
  .kr-loading--exiting { transform: none; }
}
`;

const template: LoadingTemplate = {
  css,
  rootClass: "kr-loading",
  timing,
  labels,
};

export default template;
