// Sold by Sajra brand palette. Single source of truth for colour across the
// whole site — templates derive from this, components never hardcode a hex.
//
// Values come from the live soldbysajra.com theme (--sbs-* variables):
// warm cream surfaces, deep navy for weight and contrast, antique gold as the
// accent. Keys keep the names the rest of the codebase already reads, so the
// public site and the CMS both pick the new palette up without further edits.

const colors = {
  /** Main background — cream. */
  background: "#FAF7F2",
  /** Alternate section background — deeper cream. */
  backgroundAlt: "#F0EAE0",

  /** Primary — navy. */
  primary: "#16233A",
  /** Pressed/hover navy. */
  primaryDark: "#0E1828",
  /** Lighter navy, for cards sitting on a navy surface. */
  primarySoft: "#24354F",

  /** Accent — gold. */
  accent: "#C9A961",
  /** Hover state for gold surfaces. */
  accentDark: "#B09248",
  /** Pale gold, for text and rules on navy. */
  accentLight: "#E4CD97",

  /** Main text — ink. */
  text: "#1C1C1C",
  /** Secondary text. */
  textMuted: "#6B6B6B",

  /** Soft warm borders. */
  border: "#E3DBCB",

  /** On-dark counterparts, for surfaces sitting on `primary`. */
  onPrimary: "#FFFFFF",
  onPrimaryMuted: "rgba(255, 255, 255, 0.68)",
  onPrimaryFaint: "rgba(255, 255, 255, 0.16)",
};

export default colors;
