// The site-wide section heading, with the oversized outlined ghost word.
//
// Emitted once globally by primitives/brand/brand-styles rather than per
// instance — this renders on nearly every section of the site, so injecting a
// <style> each time would duplicate the whole sheet ten times over.
//
// Three implementation notes:
//
// 1. Stacking. The brief warns against a naive `z-index: -1`, which drops the
//    ghost behind the section's own background and makes it vanish. Instead
//    the root declares `isolation: isolate` to create a local stacking
//    context, then ghost sits at z-index 0 and content at 1. No negatives, so
//    it cannot fall through whatever background the section sets.
//
// 2. Overlap. The block's top padding is derived from the ghost size, so the
//    ghost and heading keep the same relationship at every viewport instead of
//    drifting apart as the clamp resolves.
//
// 3. Centring uses a flex wrapper rather than a transform on the ghost itself,
//    which leaves `transform` free for the reveal animation.

import template1 from "./template-1";

export type SectionTitleTemplate = {
  css: string;
  /** Forces the revealed state when JavaScript never runs. */
  noscriptCss: string;
  rootClass: string;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-sectitle {
  --kr-ghost-size: ${layout.ghostSize};
  /*
   * The ghost is one long unbreakable word, so its size has to answer to how
   * many characters it has: "WHY US" and "HOW IT WORKS" cannot share a font
   * size and both fit. --kr-ghost-chars is set per instance by the component,
   * and --kr-ghost-fit takes whichever is smaller: the designed size, or the
   * size at which the word still spans the container.
   *
   * cqi needs this element to be a query container; descendants read it.
   */
  container-type: inline-size;
  --kr-ghost-fit: min(
    var(--kr-ghost-size),
    calc(100cqi / (var(--kr-ghost-chars, 8) * ${layout.ghostGlyphWidth}))
  );
  position: relative;
  /* Predictable local stacking context — see note 1. */
  isolation: isolate;
  padding-bottom: ${spacing.blockBottom}px;
  /* Belt and braces: the fit calc should prevent overflow, but a font that
     loads wider than estimated must still never widen the page. */
  overflow: hidden;
}
/* Top padding lives on the content, not the root: it is derived from the same
   fit value, and only a descendant of the container can read cqi. */
.kr-sectitle__content { padding-top: calc(var(--kr-ghost-fit) * ${layout.ghostOverlap}); }

/* Without container queries, fall back to the designed size and the old
   fixed padding — the word may crop, but nothing breaks. */
@supports not (container-type: inline-size) {
  .kr-sectitle__content { padding-top: calc(var(--kr-ghost-size) * ${layout.ghostOverlap}); }
}
@supports (overflow: clip) {
  /* clip does not create a scroll container, unlike hidden. */
  .kr-sectitle { overflow: clip; }
}

/* ── ghost word ───────────────────────────────────────── */
.kr-sectitle__ghost-wrap {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 0;
  display: flex;
  pointer-events: none;
  user-select: none;
}

.kr-sectitle__ghost {
  margin: 0 ${layout.ghostInset};
  font-family: ${typography.ghostFamily};
  font-size: var(--kr-ghost-fit, var(--kr-ghost-size));
  font-weight: ${typography.ghostWeight};
  line-height: ${layout.ghostLeading};
  letter-spacing: ${typography.ghostTracking};
  text-transform: uppercase;
  white-space: nowrap;
  /* Transparent fill plus a hairline stroke. In a browser without
     -webkit-text-stroke the word simply stays invisible, which is the correct
     degradation for something purely decorative — never a giant solid word. */
  color: transparent;
  -webkit-text-stroke: ${layout.ghostStrokeWidth}px ${color.ghostStroke};
  opacity: 0;
  transform: translateX(-16px);
  transition:
    opacity ${timing.ghost}ms ${ease} ${timing.ghostDelay}ms,
    transform ${timing.ghost}ms ${ease} ${timing.ghostDelay}ms;
}
.kr-sectitle--in .kr-sectitle__ghost {
  opacity: ${color.ghostOpacity};
  transform: none;
}

/* ── content ──────────────────────────────────────────── */
.kr-sectitle__content {
  position: relative;
  z-index: 1;
}

.kr-sectitle__title {
  margin: 0;
  max-width: ${layout.titleMaxWidth};
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: ${typography.titleLeading};
  opacity: 0;
  transform: translateY(14px);
  transition:
    opacity ${timing.title}ms ${ease} ${timing.titleDelay}ms,
    transform ${timing.title}ms ${ease} ${timing.titleDelay}ms;
}
.kr-sectitle--in .kr-sectitle__title {
  opacity: 1;
  transform: none;
}

/* The single decorative accent. */
.kr-sectitle__rule {
  display: block;
  width: ${layout.ruleWidth}px;
  height: ${layout.ruleHeight}px;
  margin: ${spacing.ruleGap}px 0 0;
  background: ${color.accent};
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform ${timing.rule}ms ${ease} ${timing.ruleDelay}ms;
}
.kr-sectitle--in .kr-sectitle__rule { transform: scaleX(1); }

.kr-sectitle__description {
  margin: ${spacing.descriptionGap}px 0 0;
  max-width: ${layout.descriptionMaxWidth};
  color: ${color.description};
  font-family: ${typography.descriptionFamily};
  font-size: ${typography.descriptionSize};
  font-weight: ${typography.descriptionWeight};
  line-height: ${typography.descriptionLeading};
  opacity: 0;
  transform: translateY(12px);
  transition:
    opacity ${timing.description}ms ${ease} ${timing.descriptionDelay}ms,
    transform ${timing.description}ms ${ease} ${timing.descriptionDelay}ms;
}
.kr-sectitle--in .kr-sectitle__description {
  opacity: 1;
  transform: none;
}

/* ── alignment ────────────────────────────────────────── */
.kr-sectitle--left .kr-sectitle__ghost-wrap { justify-content: flex-start; }
.kr-sectitle--center .kr-sectitle__ghost-wrap { justify-content: center; }
.kr-sectitle--right .kr-sectitle__ghost-wrap { justify-content: flex-end; }

.kr-sectitle--center .kr-sectitle__content { text-align: center; }
.kr-sectitle--center .kr-sectitle__title,
.kr-sectitle--center .kr-sectitle__description {
  margin-left: auto;
  margin-right: auto;
}
.kr-sectitle--center .kr-sectitle__rule {
  margin-left: auto;
  margin-right: auto;
  transform-origin: center;
}

.kr-sectitle--right .kr-sectitle__content { text-align: right; }
.kr-sectitle--right .kr-sectitle__title,
.kr-sectitle--right .kr-sectitle__description { margin-left: auto; }
.kr-sectitle--right .kr-sectitle__rule {
  margin-left: auto;
  transform-origin: right center;
}

/* ── inline variant ───────────────────────────────────── */
.kr-sectitle--inline .kr-sectitle__content {
  display: flex;
  align-items: center;
  gap: ${spacing.inlineGap}px;
}
.kr-sectitle--inline .kr-sectitle__title {
  font-size: ${typography.titleSizeInline};
  flex-shrink: 0;
}
.kr-sectitle--inline .kr-sectitle__rule { display: none; }
.kr-sectitle--inline .kr-sectitle__description {
  margin: 0;
  max-width: ${layout.descriptionMaxWidthInline};
}

.kr-sectitle__divider {
  display: block;
  flex-shrink: 0;
  width: ${layout.dividerWidth}px;
  height: ${layout.dividerHeight}px;
  background: ${color.accent};
  transform: scaleY(0);
  transition: transform ${timing.rule}ms ${ease} ${timing.ruleDelay}ms;
}
.kr-sectitle--in .kr-sectitle__divider { transform: scaleY(1); }

@media (max-width: ${layout.stackInlineBelow}px) {
  .kr-sectitle--inline .kr-sectitle__content {
    flex-direction: column;
    align-items: flex-start;
    gap: 18px;
  }
  .kr-sectitle--inline.kr-sectitle--center .kr-sectitle__content { align-items: center; }
  .kr-sectitle__divider {
    width: ${layout.ruleWidth}px;
    height: ${layout.ruleHeight}px;
    transform: scaleX(0);
    transform-origin: left center;
  }
  .kr-sectitle--in .kr-sectitle__divider { transform: scaleX(1); }
}

@media (max-width: 720px) {
  .kr-sectitle { padding-bottom: ${spacing.blockBottomCompact}px; }
}

/* ── reduced motion ───────────────────────────────────────
   Show the final state outright rather than animating into it. */
@media (prefers-reduced-motion: reduce) {
  .kr-sectitle__ghost {
    opacity: ${color.ghostOpacity};
    transform: none;
    transition: none;
  }
  .kr-sectitle__title,
  .kr-sectitle__description {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .kr-sectitle__rule { transform: scaleX(1); transition: none; }
  .kr-sectitle__divider { transform: scaleY(1); transition: none; }
  @media (max-width: ${layout.stackInlineBelow}px) {
    .kr-sectitle__divider { transform: scaleX(1); }
  }
}
`;

/**
 * Without JavaScript the in-view observer never runs, so the reveal state is
 * never applied and every section heading on the site would stay invisible.
 */
const noscriptCss = `
.kr-sectitle__ghost { opacity: ${color.ghostOpacity}; transform: none; }
.kr-sectitle__title,
.kr-sectitle__description { opacity: 1; transform: none; }
.kr-sectitle__rule { transform: scaleX(1); }
.kr-sectitle__divider { transform: scaleY(1); }
`;

const template: SectionTitleTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-sectitle",
};

export default template;
